// Nome do projeto: BlinkBinario
// Microcontrolador: Arduino UNO R3

// Define os pinos digitais para os LEDs
const int ledPin1 = 7; // LED 1: Pisca a cada 2 segundos (1s ligado, 1s desligado)
const int ledPin2 = 8; // LED 2: Fica 2 segundos aceso e 1 segundo desligado

// Variáveis de controle de tempo para o LED 1
// previousMillis1 armazena o último momento em que o LED 1 foi atualizado
unsigned long previousMillis1 = 0;
// interval1 define o tempo que o LED 1 permanece em um estado (ligado ou desligado)
const long interval1 = 1000; // 1 segundo
// ledState1 armazena o estado atual do LED 1 (HIGH para ligado, LOW para desligado)
int ledState1 = LOW;

// Variáveis de controle de tempo para o LED 2
// previousMillis2 armazena o último momento em que o LED 2 foi atualizado
unsigned long previousMillis2 = 0;
// onDuration2 define o tempo que o LED 2 permanece aceso
const long onDuration2 = 2000; // 2 segundos
// offDuration2 define o tempo que o LED 2 permanece desligado
const long offDuration2 = 1000; // 1 segundo
// ledState2 armazena o estado atual do LED 2 (HIGH para ligado, LOW para desligado)
int ledState2 = LOW;

void setup() {
  // Configura os pinos dos LEDs como saída para que possam controlar os LEDs
  pinMode(ledPin1, OUTPUT);
  pinMode(ledPin2, OUTPUT);

  // Garante que ambos os LEDs comecem desligados ao iniciar o programa
  digitalWrite(ledPin1, LOW);
  digitalWrite(ledPin2, LOW);
}

void loop() {
  // Obtém o tempo atual em milissegundos desde que o Arduino começou a executar
  // Esta função é essencial para implementações de temporização não-bloqueantes
  unsigned long currentMillis = millis();

  // Lógica para o LED 1: Pisca a cada 2 segundos (1s ligado, 1s desligado)
  // Verifica se o tempo decorrido desde a última atualização do LED 1 é maior ou igual ao seu intervalo
  if (currentMillis - previousMillis1 >= interval1) {
    // Salva o tempo atual como o último momento de atualização para o próximo ciclo
    previousMillis1 = currentMillis;

    // Inverte o estado do LED 1: se estava LOW (desligado), muda para HIGH (ligado), e vice-versa
    if (ledState1 == LOW) {
      ledState1 = HIGH;
    } else {
      ledState1 = LOW;
    }

    // Escreve o novo estado (ligado ou desligado) no pino do LED 1
    digitalWrite(ledPin1, ledState1);
  }

  // Lógica para o LED 2: Fica 2 segundos aceso e 1 segundo desligado
  // Controla o LED 2 com base em seu estado atual (aceso ou desligado)
  if (ledState2 == LOW) { // Se o LED 2 estiver atualmente desligado
    // Verifica se o tempo em que o LED 2 deveria ficar desligado (offDuration2) já passou
    if (currentMillis - previousMillis2 >= offDuration2) {
      // Liga o LED 2
      digitalWrite(ledPin2, HIGH);
      ledState2 = HIGH;
      // Salva o tempo atual como o início do período em que o LED ficará ligado
      previousMillis2 = currentMillis;
    }
  } else { // Se o LED 2 estiver atualmente aceso
    // Verifica se o tempo em que o LED 2 deveria ficar ligado (onDuration2) já passou
    if (currentMillis - previousMillis2 >= onDuration2) {
      // Desliga o LED 2
      digitalWrite(ledPin2, LOW);
      ledState2 = LOW;
      // Salva o tempo atual como o início do período em que o LED ficará desligado
      previousMillis2 = currentMillis;
    }
  }
}
